// Follow-up 1b acceptance: readableError over the real API's messages. The corpus is generated by
// apps/api/api_tests/test_followups_acceptance.py (which fails if the API's messages drift; regenerate
// with EAP_REGEN_API_ERRORS=1), so these are strings pydantic and the routes actually produce.
import { describe, expect, it } from "vitest";
import corpus from "./fixtures/apiErrors.json";
import { readableError, readablePath } from "@/components/agents/readableError";
import { errorTarget } from "@/components/agents/specSections";
import { stepForError } from "@/components/agents/stepper/registry";

type Item = { case: string; status: number; message: string; loc: (string | number)[][] };
const items = corpus as Item[];
const byCase = (name: string) => items.find((i) => i.case === name)!;

const READABLE: Record<string, string> = {
  "empty name": "Name cannot be empty",
  "missing name": "Field required",
  "long name": "Name must be at most 100 characters",
  "blank provider": "Provider cannot be empty",
  "duplicate tool": "Duplicate tool id: a.b",
  "bad tool id": "Tool id must match ^[a-z][a-z0-9_.-]{0,63}$ (ASCII only, max 64 chars): Bad Tool",
  "unknown key": "Extra inputs are not permitted",
  "context field": "Context field name must match ^[a-z][a-z0-9_]{0,31}$, Field required",
  "model not allowed": "Model 'nope:x' is not allowed on this platform (not in the EAP_ALLOWED_MODELS allowlist)",
  "moderation model not allowed": "Processor model 'nope:m' is not allowed on this platform (not in the EAP_ALLOWED_MODELS allowlist)",
  "embedding model not allowed":
    "Memory › Semantic recall: embedding model 'nope:e' is not allowed on this platform (not in the EAP_ALLOWED_EMBEDDING_MODELS allowlist)",
  "observer model not allowed": "Observer model 'nope:o' is not allowed on this platform (not in the EAP_ALLOWED_MODELS allowlist)",
  "working memory schema": "Working memory is invalid at a: unsupported type 'date'",
  "template and schema": "Set either template or json_schema, not both",
  "blank template": "Template cannot be blank",
  "semantic recall needs a model": "Field required, Input should be greater than or equal to 1",
};

describe("readableError over real API messages", () => {
  it("has a corpus covering pydantic errors, route policy errors and 422 lists", () => {
    expect(items.length).toBeGreaterThanOrEqual(25);
    expect(new Set(items.map((i) => i.status))).toEqual(new Set([422]));
  });

  it.each(Object.entries(READABLE))("%s", (name, expected) => {
    expect(readableError(byCase(name).message)).toBe(expected);
  });

  it("never leaves pydantic's prefixes or Python tuples in any message, and is idempotent", () => {
    for (const { case: name, message } of items) {
      const text = readableError(message);
      expect(text, name).not.toMatch(/Value error, |Assertion failed, |\('body'/);
      expect(readableError(text), name).toBe(text);
      expect(text.charAt(0), name).toBe(text.charAt(0).toUpperCase());
      // Only the prefix, the casing and the location words change: the message's last clause survives.
      const tail = message.replace(/Value error, /g, "").split(": ").pop()!.toLowerCase();
      expect(text.toLowerCase().endsWith(tail), name).toBe(true);
    }
  });

  it("messages without a spec location only lose a prefix and gain a capital", () => {
    for (const name of ["missing name", "unknown processor type", "model setting type", "instructions type"]) {
      const raw = byCase(name).message;
      expect(readableError(raw)).toBe(raw.charAt(0).toUpperCase() + raw.slice(1));
    }
  });

  it("names every real error location in the editor's words", () => {
    const names = items.flatMap((i) => i.loc.map((l) => readablePath(l)));
    expect(names.length).toBeGreaterThan(20);
    for (const n of names) {
      expect(n).not.toMatch(/^(Body|Spec)\b/);
      expect(n).not.toContain("_");
      expect(n).not.toMatch(/\.\d|\[\d/);
    }
    expect(readablePath(byCase("blank provider").loc[0])).toBe("Model › Provider");
    expect(readablePath(byCase("output moderation blank provider").loc[0])).toMatch(/^Output processor 2 › .*› Provider$/);
    expect(readablePath(byCase("duplicate tool").loc[0])).toBe("Tool");
    expect(readablePath(byCase("context field").loc[0])).toBe("Request context field 1 › Name");
    expect(readablePath(byCase("empty name").loc[0])).toBe("Name");
  });
});

describe("routing keeps using the raw message", () => {
  it("routes the policy errors by their raw text, which the displayed text would no longer match", () => {
    const processor = byCase("moderation model not allowed");
    expect(errorTarget(processor.message)).toEqual({ kind: "processors" });
    expect(errorTarget(readableError(processor.message))).toBeNull(); // "Processor model ..." (capital P)
    const ctx = byCase("context field");
    expect(errorTarget(ctx.message)).toEqual({ kind: "context_fields" });
    expect(errorTarget("input_processors[1].config.patterns[0]: invalid RE2 pattern")).toEqual({ kind: "processor", phase: "input", index: 1 });
    expect(errorTarget(readableError("input_processors[1].config.patterns[0]: invalid RE2 pattern"))).toBeNull();
  });

  it.each([
    ["empty name", "identity"],
    ["blank provider", "identity"],
    ["moderation blank provider", "processors"],
    ["output moderation blank provider", "processors"],
    ["max_length zero", "processors"],
    ["duplicate tool", "tools"],
    ["instructions type", "instructions"],
    ["context field", "request-context"],
    ["bad memory scope", "memory"],
    ["working memory schema", "memory"],
    ["embedding model not allowed", "memory"],
    ["observer model not allowed", "memory"],
    ["moderation model not allowed", "processors"],
  ])("%s goes to the %s step", (name, step) => {
    const item = byCase(name);
    expect(stepForError(item.message, undefined, item.loc)).toBe(step);
  });
});
